import * as React from "react";
import * as AccordionPrimitive from "@radix-ui/react-accordion";
import { cn } from "../utils";

/** 아코디언 루트 컴포넌트. 하나 이상의 접이식 패널을 관리한다. */
const Accordion = AccordionPrimitive.Root;

/** 아코디언의 개별 항목 컴포넌트 */
const AccordionItem = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Item>
>(({ className, ...props }, ref) => (
  <AccordionPrimitive.Item
    ref={ref}
    className={cn("border-b border-[var(--axis-border-default)]", className)}
    {...props}
  />
));
AccordionItem.displayName = "AccordionItem";

/** 아코디언 항목의 펼침/접힘을 토글하는 트리거 버튼 */
const AccordionTrigger = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Trigger>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Header className="flex">
    <AccordionPrimitive.Trigger
      ref={ref}
      className={cn(
        "flex flex-1 items-center justify-between py-4 font-medium transition-all",
        "text-[var(--axis-text-primary)]",
        "hover:underline",
        "[&[data-state=open]>svg]:rotate-180",
        className
      )}
      {...props}
    >
      {children}
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width="16"
        height="16"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        className="shrink-0 text-[var(--axis-text-secondary)] transition-transform duration-200"
      >
        <path d="m6 9 6 6 6-6" />
      </svg>
    </AccordionPrimitive.Trigger>
  </AccordionPrimitive.Header>
));
AccordionTrigger.displayName = "AccordionTrigger";

/** 아코디언 항목의 펼쳐지는 콘텐츠 영역 */
const AccordionContent = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Content>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Content
    ref={ref}
    className="overflow-hidden text-sm transition-all data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down motion-reduce:!animate-none"
    {...props}
  >
    <div className={cn("pb-4 pt-0", className)}>{children}</div>
  </AccordionPrimitive.Content>
));
AccordionContent.displayName = "AccordionContent";

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils";

const alertVariants = cva(
  "relative w-full rounded-lg border p-4 [&>svg~*]:pl-7 [&>svg]:absolute [&>svg]:left-4 [&>svg]:top-4 [&>svg]:text-current",
  {
    // 아이콘은 기본 클래스 [&>svg]:text-current로 변형의 글자색(text-*)을 따른다.
    // 라이트 icon-success(#22C55E) · icon-warning(#EAB308)은 상태 배경 대비가 2.18:1 · 1.85:1로
    // 비텍스트 기준 3:1에 못 미치므로 아이콘 색에 쓰지 않는다(글자색은 4.76:1 이상).
    variants: {
      variant: {
        default:
          "bg-[var(--axis-surface-default)] text-[var(--axis-text-primary)] border-[var(--axis-border-default)]",
        info: "bg-[var(--axis-surface-info)] text-[var(--axis-text-info)] border-[var(--axis-border-info)]",
        success:
          "bg-[var(--axis-surface-success)] text-[var(--axis-text-success)] border-[var(--axis-border-success)]",
        warning:
          "bg-[var(--axis-surface-warning)] text-[var(--axis-text-warning)] border-[var(--axis-border-warning)]",
        destructive:
          "bg-[var(--axis-surface-error)] text-[var(--axis-text-error)] border-[var(--axis-border-error)]",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
);

/**
 * Alert 컴포넌트 Props
 * @property variant - 알림 스타일 변형 (default, info, success, warning, destructive)
 */
export interface AlertProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof alertVariants> {}

/** 사용자에게 중요한 메시지를 전달하는 알림 컴포넌트 */
const Alert = React.forwardRef<HTMLDivElement, AlertProps>(
  ({ className, variant, ...props }, ref) => (
    <div
      ref={ref}
      role="alert"
      className={cn(alertVariants({ variant }), className)}
      {...props}
    />
  )
);
Alert.displayName = "Alert";

/** 알림의 제목을 표시하는 컴포넌트 */
const AlertTitle = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLHeadingElement>
>(({ className, ...props }, ref) => (
  <h5
    ref={ref}
    className={cn("mb-1 font-medium leading-none tracking-tight", className)}
    {...props}
  />
));
AlertTitle.displayName = "AlertTitle";

/** 알림의 상세 설명을 표시하는 컴포넌트 */
const AlertDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, ...props }, ref) => (
  <div
    ref={ref}
    className={cn("text-sm [&_p]:leading-relaxed", className)}
    {...props}
  />
));
AlertDescription.displayName = "AlertDescription";

export { Alert, AlertTitle, AlertDescription, alertVariants };

import * as React from "react";
import { type VariantProps } from "class-variance-authority";
import { cn } from "../utils";
import { avatarVariants } from "./variants";

/**
 * Avatar 컴포넌트 Props
 * @property size - 아바타 크기 (sm, default, lg, xl)
 */
export interface AvatarProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof avatarVariants> {
  /** 이미지 소스 URL */
  src?: string;
  /** 대체 텍스트 */
  alt?: string;
  /** 이미지 로드 실패 시 표시할 fallback 텍스트 */
  fallback?: string;
}

/**
 * 사용자 프로필 이미지를 표시하는 아바타 컴포넌트
 * 이미지 로드 실패 시 이니셜 fallback을 표시한다.
 *
 * 실패 판정은 두 경로다(WI-0054).
 * 1. `<img onError>`: 하이드레이션 뒤(또는 클라이언트 렌더)에 난 오류.
 * 2. 마운트 시 검사: 서버 렌더된 이미지의 오류가 하이드레이션 전에 끝나면 onError 가 붙기 전이라
 *    이벤트를 놓친다. 그래서 마운트(와 src 변경) 때 `complete && naturalWidth === 0` 이면 실패 후보로 보고,
 *    `img.decode()` 가 거부될 때만 실패로 확정한다. 고유 크기가 없는 SVG 처럼 정상 로드인데
 *    naturalWidth 가 0 일 수 있는 이미지는 decode 가 이행되므로 실패로 보지 않는다.
 *    decode 가 없는 환경에서는 판정하지 않는다(종전 동작).
 *
 * 실패 상태는 실패한 src 와 함께 기억한다. src 가 바뀌면 렌더 중에 초기화해 새 이미지를 다시 시도한다.
 */
const Avatar = React.forwardRef<HTMLDivElement, AvatarProps>(
  ({ className, size, src, alt, fallback, ...props }, ref) => {
    // 실패한 src. null 이면 실패 없음
    const [failedSrc, setFailedSrc] = React.useState<string | null>(null);
    if (failedSrc !== null && failedSrc !== src) {
      // src 가 바뀌면 이전 실패를 지운다(렌더 중 상태 조정)
      setFailedSrc(null);
    }
    const hasError = failedSrc !== null && failedSrc === src;
    const imgRef = React.useRef<HTMLImageElement>(null);

    React.useEffect(() => {
      const img = imgRef.current;
      if (!img || !src) return;
      // 아직 로딩 중이면 onError 가 받는다. 크기가 있으면 정상 로드다
      if (!img.complete || img.naturalWidth !== 0) return;
      if (typeof img.decode !== "function") return;
      let cancelled = false;
      img.decode().then(
        () => undefined,
        () => {
          if (!cancelled) setFailedSrc(src);
        }
      );
      return () => {
        cancelled = true;
      };
    }, [src]);

    const initials = React.useMemo(() => {
      if (fallback) return fallback;
      if (!alt) return "?";
      return alt
        .split(" ")
        .map((word) => word[0])
        .join("")
        .toUpperCase()
        .slice(0, 2);
    }, [alt, fallback]);

    return (
      <div
        ref={ref}
        className={cn(avatarVariants({ size, className }))}
        {...props}
      >
        {src && !hasError ? (
          <img
            ref={imgRef}
            src={src}
            alt={alt || "Avatar"}
            className="aspect-square h-full w-full object-cover"
            onError={() => setFailedSrc(src)}
          />
        ) : (
          <span className="flex h-full w-full items-center justify-center bg-[var(--axis-surface-tertiary)] text-[var(--axis-text-secondary)] font-medium">
            {initials}
          </span>
        )}
      </div>
    );
  }
);
Avatar.displayName = "Avatar";

export { Avatar };

/**
 * 사용자 프로필 이미지를 표시하는 아바타 컴포넌트
 * 이미지 로드 실패 시 이니셜 fallback을 표시한다.
 *
 * 이 파일은 `./avatar`(클라이언트 경계) 와 `./variants`(서버에서도 호출 가능) 를 다시 내보내는 배럴입니다.
 * 루트와 `@axis-ds/ui-react/avatar` 의 내보내기 이름은 분리 전과 같습니다(WI-0050 D2).
 * 이 파일은 클라이언트 지시문 목록(scripts/client-modules.mjs)에 넣지 않습니다. 넣으면 서버에서 `avatarVariants()` 를 부를 수 없습니다.
 */
export { Avatar, type AvatarProps } from "./avatar";
export { avatarVariants } from "./variants";

import { cva } from "class-variance-authority";

/**
 * Avatar 크기 variants
 *
 * 컴포넌트(./avatar, 클라이언트 경계)와 파일을 나눠 두었습니다. 같은 파일에 있으면
 * 서버 컴포넌트에서 `avatarVariants()` 를 부를 때 클라이언트 참조가 되어 실패합니다(WI-0050 D2).
 * 이 파일은 클라이언트 지시문 목록(scripts/client-modules.mjs)에 넣지 않습니다.
 */
const avatarVariants = cva(
  "relative flex shrink-0 overflow-hidden rounded-full bg-[var(--axis-surface-secondary)]",
  {
    variants: {
      size: {
        sm: "h-8 w-8 text-xs",
        default: "h-10 w-10 text-sm",
        lg: "h-12 w-12 text-base",
        xl: "h-16 w-16 text-lg",
      },
    },
    defaultVariants: {
      size: "default",
    },
  }
);

export { avatarVariants };

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils";

const badgeVariants = cva(
  "inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2",
  {
    variants: {
      variant: {
        default:
          "border-transparent bg-[var(--axis-badge-default-bg)] text-[var(--axis-badge-default-text)]",
        secondary:
          "border-transparent bg-[var(--axis-surface-secondary)] text-[var(--axis-text-secondary)]",
        destructive:
          "border-transparent bg-[var(--axis-badge-error-bg)] text-[var(--axis-badge-error-text)]",
        success:
          "border-transparent bg-[var(--axis-badge-success-bg)] text-[var(--axis-badge-success-text)]",
        warning:
          "border-transparent bg-[var(--axis-badge-warning-bg)] text-[var(--axis-badge-warning-text)]",
        error:
          "border-transparent bg-[var(--axis-badge-error-bg)] text-[var(--axis-badge-error-text)]",
        info:
          "border-transparent bg-[var(--axis-badge-info-bg)] text-[var(--axis-badge-info-text)]",
        outline: "border-[var(--axis-border-default)] text-[var(--axis-text-primary)]",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
);

/**
 * Badge 컴포넌트 Props
 * @property variant - 배지 스타일 변형 (default, secondary, destructive, success, warning, error, info, outline)
 */
export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof badgeVariants> {}

/** 상태나 카테고리를 나타내는 작은 라벨 컴포넌트 */
const Badge = React.forwardRef<HTMLDivElement, BadgeProps>(
  ({ className, variant, ...props }, ref) => (
    <div
      ref={ref}
      className={cn(badgeVariants({ variant }), className)}
      {...props}
    />
  )
);
Badge.displayName = "Badge";

export { Badge, badgeVariants };

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cn } from "../utils";

/**
 * 브레드크럼 루트 네비게이션 컴포넌트
 * 현재 페이지의 계층 구조를 표시한다.
 */
const Breadcrumb = React.forwardRef<
  HTMLElement,
  React.ComponentPropsWithoutRef<"nav"> & {
    /** 항목 사이의 구분자 요소 */
    separator?: React.ReactNode;
  }
>(({ ...props }, ref) => <nav ref={ref} aria-label="breadcrumb" {...props} />);
Breadcrumb.displayName = "Breadcrumb";

/** 브레드크럼 항목들을 감싸는 정렬된 목록 */
const BreadcrumbList = React.forwardRef<
  HTMLOListElement,
  React.ComponentPropsWithoutRef<"ol">
>(({ className, ...props }, ref) => (
  <ol
    ref={ref}
    className={cn(
      "flex flex-wrap items-center gap-1.5 break-words text-sm text-[var(--axis-text-secondary)] sm:gap-2.5",
      className
    )}
    {...props}
  />
));
BreadcrumbList.displayName = "BreadcrumbList";

/** 브레드크럼의 개별 항목 컴포넌트 */
const BreadcrumbItem = React.forwardRef<
  HTMLLIElement,
  React.ComponentPropsWithoutRef<"li">
>(({ className, ...props }, ref) => (
  <li
    ref={ref}
    className={cn("inline-flex items-center gap-1.5", className)}
    {...props}
  />
));
BreadcrumbItem.displayName = "BreadcrumbItem";

/** 브레드크럼 항목의 클릭 가능한 링크 컴포넌트 */
const BreadcrumbLink = React.forwardRef<
  HTMLAnchorElement,
  React.ComponentPropsWithoutRef<"a"> & {
    /** Slot 패턴을 사용하여 자식 요소를 링크로 렌더링 */
    asChild?: boolean;
  }
>(({ asChild, className, ...props }, ref) => {
  const Comp = asChild ? Slot : "a";
  return (
    <Comp
      ref={ref}
      className={cn(
        "transition-colors hover:text-[var(--axis-text-primary)]",
        className
      )}
      {...props}
    />
  );
});
BreadcrumbLink.displayName = "BreadcrumbLink";

/** 현재 페이지를 나타내는 비활성 브레드크럼 항목 */
const BreadcrumbPage = React.forwardRef<
  HTMLSpanElement,
  React.ComponentPropsWithoutRef<"span">
>(({ className, ...props }, ref) => (
  <span
    ref={ref}
    role="link"
    aria-disabled="true"
    aria-current="page"
    className={cn("font-normal text-[var(--axis-text-primary)]", className)}
    {...props}
  />
));
BreadcrumbPage.displayName = "BreadcrumbPage";

/** 브레드크럼 항목 사이의 구분자 (기본: 화살표 아이콘) */
const BreadcrumbSeparator = ({
  children,
  className,
  ...props
}: React.ComponentProps<"li">) => (
  <li
    role="presentation"
    aria-hidden="true"
    className={cn("[&>svg]:h-3.5 [&>svg]:w-3.5", className)}
    {...props}
  >
    {children ?? (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width="16"
        height="16"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <path d="m9 18 6-6-6-6" />
      </svg>
    )}
  </li>
);
BreadcrumbSeparator.displayName = "BreadcrumbSeparator";

/** 생략된 브레드크럼 항목을 나타내는 말줄임 표시 */
const BreadcrumbEllipsis = ({
  className,
  ...props
}: React.ComponentProps<"span">) => (
  <span
    role="presentation"
    aria-hidden="true"
    className={cn("flex h-9 w-9 items-center justify-center", className)}
    {...props}
  >
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="16"
      height="16"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <circle cx="12" cy="12" r="1" />
      <circle cx="19" cy="12" r="1" />
      <circle cx="5" cy="12" r="1" />
    </svg>
    <span className="sr-only">More</span>
  </span>
);
BreadcrumbEllipsis.displayName = "BreadcrumbEllipsis";

export {
  Breadcrumb,
  BreadcrumbList,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbPage,
  BreadcrumbSeparator,
  BreadcrumbEllipsis,
};

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center whitespace-nowrap rounded-[var(--axis-radius-control,0.375rem)] text-[length:var(--axis-control-font-size-md,0.875rem)] leading-5 font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
  {
    variants: {
      variant: {
        default:
          "bg-[var(--axis-button-bg-default)] text-[var(--axis-button-text-default)] hover:bg-[var(--axis-button-bg-hover)] active:bg-[var(--axis-button-bg-active)] focus-visible:ring-[var(--axis-button-border-focus)]",
        secondary:
          "bg-[var(--axis-button-secondary-bg-default)] text-[var(--axis-button-secondary-text-default)] hover:bg-[var(--axis-button-secondary-bg-hover)] active:bg-[var(--axis-button-secondary-bg-active)]",
        ghost:
          "bg-[var(--axis-button-ghost-bg-default)] text-[var(--axis-button-ghost-text-default)] hover:bg-[var(--axis-button-ghost-bg-hover)] active:bg-[var(--axis-button-ghost-bg-active)]",
        destructive:
          "bg-[var(--axis-button-destructive-bg-default)] text-[var(--axis-button-destructive-text-default)] hover:bg-[var(--axis-button-destructive-bg-hover)] active:bg-[var(--axis-button-destructive-bg-active)]",
        outline:
          "border border-[var(--axis-border-default)] bg-transparent hover:bg-[var(--axis-surface-secondary)] text-[var(--axis-text-primary)]",
        link: "text-[var(--axis-text-brand)] underline-offset-4 hover:underline",
      },
      size: {
        sm: "h-[var(--axis-control-h-sm,2rem)] px-3 text-[length:var(--axis-control-font-size-sm,0.75rem)] leading-4",
        default: "h-[var(--axis-control-h-md,2.5rem)] px-4 py-2",
        lg: "h-[var(--axis-control-h-lg,3rem)] px-6 text-[length:var(--axis-control-font-size-lg,1rem)] leading-6",
        icon: "h-[var(--axis-control-h-md,2.5rem)] w-[var(--axis-control-h-md,2.5rem)]",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

/**
 * Button 컴포넌트 Props
 * @property variant - 버튼 스타일 변형 (default, secondary, ghost, destructive, outline, link)
 * @property size - 버튼 크기 (sm, default, lg, icon)
 */
export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  /** Slot 패턴을 사용하여 자식 요소를 버튼으로 렌더링 */
  asChild?: boolean;
}

/** 다양한 스타일 변형과 크기를 지원하는 버튼 컴포넌트 */
const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return (
      <Comp
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    );
  }
);
Button.displayName = "Button";

export { Button, buttonVariants };

